) HEADER (
    user-agent "because-agent you@example.com"
) BODY ();

CREATE SCHEMASTORE VIEW edgar_concept_0000050863_revenues WITH CONTAINER because AS
SELECT
    CAST(cik AS STRING) AS cik,
    `entityName` AS entity_name,
    tag AS concept,
    fact.`start` AS period_start,
    fact.`end` AS period_end,
    CAST(fact.val AS DOUBLE) AS value_usd,
    fact.accn AS accession_number,
    CAST(fact.fy AS BIGINT) AS fiscal_year,
    fact.fp AS fiscal_period,
    fact.form AS form_type,
    fact.filed AS filed_date
FROM because_rest.edgar_concept_0000050863_revenues_raw
LATERAL VIEW explode(units.USD) AS fact;

