    endpoint "https://api.stlouisfed.org/fred/series/observations?series_id=INDPRO&api_key=***&file_type=json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
) BODY ();

CREATE SCHEMASTORE VIEW fred_series_indpro WITH CONTAINER because AS
SELECT
    'INDPRO' AS series_id,
    o.date AS period,
    CAST(o.value AS DOUBLE) AS value
FROM because_rest.fred_series_indpro_raw
LATERAL VIEW explode(observations) AS o;

